"""Real MCP subprocess context/skill reads and clarification receipts; no native inference."""
from pathlib import Path
import json,os,subprocess,sys,tempfile,unittest
from urace import executor_capabilities as ec
import project_tools

class CapabilityToolPipelineTests(unittest.TestCase):
 def test_real_mcp_middle_passage_question_and_skill_reads_are_logged(self):
  with tempfile.TemporaryDirectory() as d:
   root=Path(d);workspace=root/'project';workspace.mkdir();packet=ec.prepare({},'codex',{'family':'receipts','requirements':[{'id':'r'+str(i),'title':'Task '+str(i),'success_measure':'Independent public check'} for i in range(61)]});context=root/'context.json';log=root/'tools.jsonl';context.write_text(json.dumps({'workspace':str(workspace),'allowed_files':['logic.py'],'public_checks':str(root/'public.py'),'tool_log':str(log),'capabilities':packet}));requests=[{'jsonrpc':'2.0','id':1,'method':'tools/call','params':{'name':'read_file','arguments':{'path':'@requirement/r30'}}},{'jsonrpc':'2.0','id':2,'method':'tools/call','params':{'name':'read_file','arguments':{'path':'@skill/urace-receipt-review'}}},{'jsonrpc':'2.0','id':3,'method':'tools/call','params':{'name':'write_file','arguments':{'path':'@question/r30','content':json.dumps({'question':'Need owner meaning','needs_owner':True})}}}];env={**os.environ,'PYTHONPATH':str(Path(__file__).parent.parent/'runtime')+os.pathsep+os.environ.get('PYTHONPATH','')};result=subprocess.run([sys.executable,str(Path(project_tools.__file__)),str(context)],input=''.join(json.dumps(r)+'\n' for r in requests),capture_output=True,text=True,env=env,timeout=15);self.assertEqual(result.returncode,0,result.stderr);responses=[json.loads(line) for line in result.stdout.splitlines()];self.assertEqual(len(responses),3);self.assertTrue(all(not r['result'].get('isError') for r in responses));events=[json.loads(line) for line in log.read_text().splitlines()];feedback=ec.feedback(packet,events);self.assertEqual(feedback['explicit_requirement_reads'],['r30']);self.assertEqual(feedback['skill_instruction_reads'],['urace-receipt-review']);self.assertEqual(feedback['status'],'AWAITING_OWNER_CLARIFICATION');self.assertGreater(feedback['context_response_bytes'],0);self.assertFalse(feedback['understanding_proven']);self.assertEqual(list(workspace.iterdir()),[])
